                    token.text[writeIndex++] = c;
                    lexer->position++;
                } else {
                    token.text[writeIndex] = '\0';
                    token.kind = TOKEN_IDENT;
                    state = STATE_DONE;
                }
                break;
            case STATE_DONE:
                break;
        }
    }
    return token;
}

int countTokens(const char *source) {
    Lexer lexer;
    lexerInit(&lexer, source);
    int total = 0;
    Token token = lexerNext(&lexer);
    while (token.kind != TOKEN_END) {
        total++;
        token = lexerNext(&lexer);
    }
    return total;
}

