    b7 = (code >> 6) & 1;
    data = b3 | (b5 << 1) | (b6 << 2) | (b7 << 3);
    result->corrected = (uint8_t)data;
}

int hamming_distance(uint8_t a, uint8_t b) {
    return parity_of(a ^ b) ? -1 : 0;
