        if (c == ')') {
            if (!emitToken(list, TOKEN_RPAREN, source, i, i + 1)) break;
            i++;
            continue;
        }

        /* Two-character relational operators: <=, >=, ==, != take priority
         * over their single-character forms when the second char matches. */
        if ((c == '<' || c == '>' || c == '=' || c == '!') && source[i + 1] == '=') {
