/*
 * union_find.c
 *
 * A disjoint-set (union-find) data structure with both path compression and
 * union by rank. These two optimisations together make a sequence of
 * operations run in near-constant amortised time (inverse Ackermann).
 */

#include <stdio.h>
#include <stdlib.h>

/*
 * The forest of sets. Each element points at a parent; a root points at
 * itself. `rank` is an upper bound on a tree's height used to keep unions
 * shallow. `setCount` tracks how many distinct sets currently exist.
 */
typedef struct DisjointSet {
    int *parent;    /* parent[i] is i's parent, or i itself if i is a root */
    int *rank;      /* rank[i] is a height bound for the tree rooted at i */
    int count;      /* total number of elements */
    int setCount;   /* number of distinct sets remaining */
} DisjointSet;

/*
 * Create a structure of `count` elements, each in its own singleton set.
 * Returns NULL on allocation failure; caller frees with dsuDestroy.
 */
DisjointSet *dsuCreate(int count) {
    DisjointSet *d = (DisjointSet *)malloc(sizeof(DisjointSet));
    if (d == NULL) {
        return NULL;
    }
    d->parent = (int *)malloc((size_t)count * sizeof(int));
    d->rank = (int *)calloc((size_t)count, sizeof(int));  /* all ranks start 0 */
    if (d->parent == NULL || d->rank == NULL) {
        free(d->parent);
        free(d->rank);
        free(d);
        return NULL;
    }
    for (int i = 0; i < count; i++) {
        d->parent[i] = i;   /* every element is initially its own root */
    }
    d->count = count;
    d->setCount = count;    /* count singletons == count sets */
    return d;
}

/*
 * Find the representative (root) of the set containing x, applying path
 * compression so future lookups are faster. Amortised near-O(1).
 * Returns -1 if x is out of range.
 */
int dsuFind(DisjointSet *d, int x) {
    if (x < 0 || x >= d->count) {
        return -1;
    }
    /* Walk to the root. */
    int root = x;
    while (d->parent[root] != root) {
        root = d->parent[root];
    }
    /* Second pass: point every node on the path directly at the root. */
    while (d->parent[x] != root) {
        int next = d->parent[x];
        d->parent[x] = root;
        x = next;
    }
    return root;
}

/*
 * Merge the sets containing a and b. Uses union by rank: the shorter tree is
 * hung under the taller one to limit growth. Returns 1 if a merge happened, 0
 * if a and b were already in the same set, or -1 on invalid indices.
 */
int dsuUnion(DisjointSet *d, int a, int b) {
    int ra = dsuFind(d, a);
    int rb = dsuFind(d, b);
    if (ra < 0 || rb < 0) {
        return -1;
    }
    if (ra == rb) {
        return 0;   /* already connected; nothing to do */
    }
    /* Attach the lower-rank root beneath the higher-rank root. */
    if (d->rank[ra] < d->rank[rb]) {
        d->parent[ra] = rb;
    } else if (d->rank[ra] > d->rank[rb]) {
        d->parent[rb] = ra;
    } else {
        /* Equal ranks: pick one root and bump its rank by one. */
        d->parent[rb] = ra;
        d->rank[ra]++;
    }
    d->setCount--;   /* two sets became one */
    return 1;
}

/*
 * Return 1 if a and b belong to the same set, else 0 (or -1 on bad indices).
 */
int dsuConnected(DisjointSet *d, int a, int b) {
    int ra = dsuFind(d, a);
    int rb = dsuFind(d, b);
    if (ra < 0 || rb < 0) {
        return -1;
    }
    return ra == rb ? 1 : 0;
}

/*
 * Free the internal arrays and the structure itself. NULL is ignored.
 */
void dsuDestroy(DisjointSet *d) {
    if (d == NULL) {
        return;
    }
    free(d->parent);
    free(d->rank);
    free(d);
}

/*
 * daycount.c — Serial day numbers and date arithmetic.
 *
 * Converts Gregorian dates to and from a continuous integer day count (days
 * since a fixed epoch). With dates reduced to integers, differences and offset
 * arithmetic become simple subtraction and addition.
 */

#include <stdint.h>

/* A Gregorian calendar date. */
typedef struct {
    int year;
    int month;   /* 1..12 */
    int day;     /* 1..31 */
} Date;

/*
 * isLeap — Internal leap-year predicate (Gregorian rules).
 *
 * Parameters: year — the year to test.
 * Returns: 1 if leap, 0 otherwise.
 */
static int isLeap(int year) {
    return (year % 4 == 0 && year % 100 != 0) || (year % 400 == 0);
}

/*
 * toSerial — Convert a date to a serial day number.
 *
 * Implements a well-known integer algorithm that maps a Gregorian date onto a
 * continuous day count by treating March as the start of the year, which moves
 * the irregular leap day to the very end and removes month-length special
 * cases from the core arithmetic.
 *
 * Parameters:
 *   d — the date to convert (assumed valid).
 * Returns:
 *   A 64-bit serial day number; the absolute epoch is unspecified but stable,
 *   so differences between two serial numbers give an exact day count.
 * Complexity: O(1).
 */
int64_t toSerial(Date d) {
    int y = d.year;
    int m = d.month;

    /* Shift so that March = month 0; Jan/Feb roll into the previous year. */
    int a = (14 - m) / 12;   /* 1 for Jan/Feb, else 0 */
    y = y + 4800 - a;        /* offset to keep all working values positive */
    m = m + 12 * a - 3;      /* remap month to 0..11 with March = 0 */

    /*
     * (153*m + 2)/5 is the running day offset of each remapped month; the
     * year terms add the accumulated leap days. The trailing -32045 anchors
     * the count to the conventional epoch.
     */
    return d.day
         + (153 * (int64_t)m + 2) / 5
         + 365LL * y
         + y / 4
         - y / 100
         + y / 400
         - 32045;
}

/*
 * fromSerial — Convert a serial day number back to a Gregorian date.
 *
 * Exact inverse of toSerial(); the two round-trip for any valid date.
 *
 * Parameters:
 *   serial — a serial day number produced by toSerial().
 * Returns:
 *   The corresponding Date.
 * Complexity: O(1).
 */
Date fromSerial(int64_t serial) {
    int64_t a = serial + 32044;
    int64_t b = (4 * a + 3) / 146097;     /* which 400-year cycle */
    int64_t c = a - (146097 * b) / 4;     /* day within that cycle */

    int64_t y = (4 * c + 3) / 1461;       /* year within the cycle */
    int64_t day_in_year = c - (1461 * y) / 4;
    int64_t m = (5 * day_in_year + 2) / 153;  /* remapped month, March = 0 */

    Date result;
    result.day   = (int)(day_in_year - (153 * m + 2) / 5 + 1);
    result.month = (int)(m + 3 - 12 * (m / 10));  /* undo the March-shift */
    result.year  = (int)(100 * b + y - 4800 + m / 10);
    return result;
}

/*
 * daysBetween — Signed number of days from one date to another.
 *
 * Parameters:
 *   from — the earlier (or reference) date.
 *   to   — the later date.
 * Returns:
 *   to - from in days; negative if `to` precedes `from`.
 */
int64_t daysBetween(Date from, Date to) {
    return toSerial(to) - toSerial(from);
}

/*
 * addDays — Produce the date that lies `offset` days from a starting date.
 *
 * Parameters:
 *   start  — the base date.
 *   offset — number of days to add; may be negative to move backward.
 * Returns:
 *   The resulting Date, with month and year carry handled automatically.
 */
Date addDays(Date start, int64_t offset) {
    return fromSerial(toSerial(start) + offset);
}

