/*
 * trie.c — Prefix tree (trie) over lowercase ASCII letters.
 *
 * A trie stores a set of words as a tree where each edge is labeled by a
 * letter and each path from the root spells a prefix. It supports fast exact
 * lookup, prefix queries, and counting, all proportional to the length of the
 * key rather than the number of stored words.
 */

#include <stdlib.h>
#include <string.h>

/* Branching factor: one child slot per lowercase letter 'a'..'z'. */
#define TRIE_WIDTH 26

/*
 * A single node in the trie. `children` indexes by (letter - 'a'); a NULL
 * slot means that letter does not continue any stored word here.
 * `is_terminal` marks the end of an inserted word, and `word_count` records
 * how many times the word ending here was inserted (supports multisets).
 */
typedef struct TrieNode {
    struct TrieNode *children[TRIE_WIDTH];
    int is_terminal;
    int word_count;
} TrieNode;

/*
 * Allocate and zero-initialize a fresh trie node.
 *
 * Returns a pointer to the new node, or NULL on allocation failure. All child
 * pointers start NULL and the node is non-terminal.
 */
static TrieNode *trie_node_create(void) {
    TrieNode *node = calloc(1, sizeof(TrieNode));
    return node; /* calloc already zeroed children, is_terminal, word_count. */
}

/*
 * Create an empty trie and return its root node.
 *
 * Returns the root, or NULL on allocation failure. The caller owns the trie
 * and must release it with trie_free.
 */
TrieNode *trie_create(void) {
    return trie_node_create();
}

/*
 * Insert `word` into the trie, creating nodes along the way as needed.
 *
 * Returns 1 on success, 0 on allocation failure or if `word` contains a
 * character outside 'a'..'z'. Re-inserting an existing word increments its
 * count rather than failing. Complexity: O(length of word).
 */
int trie_insert(TrieNode *root, const char *word) {
    TrieNode *node = root;
    for (const char *p = word; *p; p++) {
        int index = *p - 'a';
        if (index < 0 || index >= TRIE_WIDTH) {
            return 0;        /* Reject anything outside the supported alphabet. */
        }
        if (!node->children[index]) {
            node->children[index] = trie_node_create();
            if (!node->children[index]) {
                return 0;    /* Out of memory midway; partial path is harmless. */
            }
        }
        node = node->children[index];
    }
    node->is_terminal = 1;   /* Mark the final node as a complete word. */
    node->word_count++;
    return 1;
}

/*
 * Walk the trie following `key` and return the node it lands on.
 *
 * Returns the node reached after consuming every character of `key`, or NULL
 * if the path breaks anywhere. Shared by lookup and prefix queries.
 * Complexity: O(length of key).
 */
static TrieNode *trie_descend(TrieNode *root, const char *key) {
    TrieNode *node = root;
    for (const char *p = key; *p; p++) {
        int index = *p - 'a';
        if (index < 0 || index >= TRIE_WIDTH || !node->children[index]) {
            return NULL;     /* Out-of-alphabet or missing edge: no such path. */
        }
        node = node->children[index];
    }
    return node;
}

/*
 * Test whether `word` was inserted into the trie as a complete word.
 *
 * Returns 1 if present, 0 otherwise. A prefix that is not itself a stored
 * word returns 0 even though its path exists. Complexity: O(length of word).
 */
int trie_contains(TrieNode *root, const char *word) {
    TrieNode *node = trie_descend(root, word);
    return node != NULL && node->is_terminal;
}

/*
 * Test whether any stored word starts with `prefix`.
 *
 * Returns 1 if at least one inserted word has `prefix` as a prefix, else 0.
 * The empty prefix returns 1 as long as the trie has any node (the root).
 * Complexity: O(length of prefix).
 */
int trie_starts_with(TrieNode *root, const char *prefix) {
    return trie_descend(root, prefix) != NULL;
}

/*
 * Count the number of distinct stored words in the subtree rooted at `node`.
 *
 * Returns that count. A terminal node contributes 1 regardless of its
 * word_count multiplicity. Complexity: O(number of nodes in the subtree).
 */
int trie_count_words(TrieNode *node) {
    if (!node) return 0;
    int total = node->is_terminal ? 1 : 0;
    for (int i = 0; i < TRIE_WIDTH; i++) {
        total += trie_count_words(node->children[i]);
    }
    return total;
}

/*
 * Recursively free the trie rooted at `node`, including `node` itself.
 *
 * Safe to call with NULL. After this returns the pointer is dangling and must
 * not be used. Complexity: O(number of nodes).
 */
void trie_free(TrieNode *node) {
    if (!node) return;
    for (int i = 0; i < TRIE_WIDTH; i++) {
        trie_free(node->children[i]);
    }
    free(node);
}

/*
 * LZW dictionary-based compressor.
 *
 * LZW builds a dictionary of byte strings on the fly: it starts with all 256
 * single-byte entries and adds a new multi-byte entry every time it emits a
 * code. Because the decoder rebuilds the identical dictionary from the code
 * stream alone, no table is transmitted. This implementation uses a simple
 * hash map keyed by (prefix code, next byte) for the encoder.
 */

#include <stdint.h>
#include <stdlib.h>
#include <string.h>

/* Codes 0..255 are the literal bytes; new strings start at 256. */
static const int kFirstFreeCode = 256;
/* Hash table size; a prime keeps probe sequences well spread. */
static const int kHashSize = 9973;

/*
 * One encoder dictionary slot mapping a (prefix, suffix) pair to its code.
 *
 * An empty slot has code == -1. Collisions are resolved by linear probing.
 */
struct LzwEntry {
    int     prefix;
    uint8_t suffix;
    int     code;
};

/*
 * The encoder's open-addressed hash table plus the next code to assign.
 */
struct LzwDict {
    LzwEntry slots[kHashSize];
    int      nextCode;
};

/*
 * Reset the dictionary so only the 256 literal codes are implicitly present.
 *
 * The single-byte codes are never stored explicitly; they equal the byte
 * value, so the table only holds multi-byte strings. O(kHashSize).
 */
static void lzwDictReset(LzwDict *dict) {
    for (int i = 0; i < kHashSize; i++) {
        dict->slots[i].code = -1; /* mark empty */
    }
    dict->nextCode = kFirstFreeCode;
}

/*
 * Hash a (prefix, suffix) pair into a starting bucket index.
 *
 * Mixes the prefix code with the suffix byte; the caller linear-probes from
 * the returned index. O(1).
 */
static int lzwHash(int prefix, uint8_t suffix) {
    unsigned h = (unsigned)prefix * 257u + (unsigned)suffix + 1u;
    return (int)(h % (unsigned)kHashSize);
}

/*
 * Look up the code for (prefix, suffix), or -1 if the string is not present.
 *
 * Linear-probes until it finds a match or an empty slot. Returns the stored
 * code, or -1 when absent. O(1) amortised for a lightly loaded table.
 */
static int lzwLookup(const LzwDict *dict, int prefix, uint8_t suffix) {
    int idx = lzwHash(prefix, suffix);
    while (dict->slots[idx].code != -1) {
        if (dict->slots[idx].prefix == prefix &&
            dict->slots[idx].suffix == suffix) {
            return dict->slots[idx].code;
        }
        idx = (idx + 1) % kHashSize; /* probe the next bucket */
    }
    return -1;
}

/*
 * Insert (prefix, suffix) with the next available code.
 *
 * Assumes the string is absent (caller checked via lzwLookup). Does nothing if
 * the table is effectively full, capping dictionary growth. O(1) amortised.
 */
static void lzwInsert(LzwDict *dict, int prefix, uint8_t suffix) {
    if (dict->nextCode >= kHashSize) {
        return; /* Stop growing rather than overflow the fixed table. */
    }
    int idx = lzwHash(prefix, suffix);
    while (dict->slots[idx].code != -1) {
        idx = (idx + 1) % kHashSize;
    }
    dict->slots[idx].prefix = prefix;
    dict->slots[idx].suffix = suffix;
    dict->slots[idx].code = dict->nextCode++;
}

/*
 * Compress src into an array of integer codes.
 *
 * src/srcLen : input bytes.
 * codes      : output code array, sized by the caller (codeCap entries).
 * Returns the number of codes emitted, or (size_t)-1 if codeCap is exceeded.
 * Runs in O(n) amortised thanks to the hash dictionary.
 */
size_t lzwCompress(const uint8_t *src, size_t srcLen,
                   int *codes, size_t codeCap) {
    if (srcLen == 0) {
        return 0;
    }
    LzwDict *dict = (LzwDict *)malloc(sizeof(LzwDict));
    if (!dict) {
        return (size_t)-1;
    }
    lzwDictReset(dict);

    size_t out = 0;
    int current = src[0]; /* the running string, seeded with the first byte */
    for (size_t i = 1; i < srcLen; i++) {
        uint8_t next = src[i];
        int combined = lzwLookup(dict, current, next);
        if (combined != -1) {
            /* The extended string already exists; keep growing it. */
            current = combined;
        } else {
            /* Emit the longest known string, then learn the extension. */
            if (out >= codeCap) {
                free(dict);
                return (size_t)-1;
            }
            codes[out++] = current;
            lzwInsert(dict, current, next);
            current = next;
        }
    }
    /* Flush the final pending string. */
    if (out >= codeCap) {
        free(dict);
        return (size_t)-1;
    }
    codes[out++] = current;
    free(dict);
    return out;
}

/*
 * Decompress a code stream produced by lzwCompress() back into bytes.
 *
 * The decoder rebuilds the dictionary as an array of (prefix, suffix) entries
 * and reconstructs each string by walking prefixes backward. It handles the
 * classic KwKwK case where a code refers to the entry being defined this step.
 *
 * codes/codeCount : the compressed codes.
 * dst/dstCap      : output buffer.
 * Returns the number of bytes written, or (size_t)-1 on allocation failure or
 * a malformed code. O(total output length).
 */
size_t lzwDecompress(const int *codes, size_t codeCount,
                     uint8_t *dst, size_t dstCap) {
    if (codeCount == 0) {
        return 0;
    }
    /* Parallel arrays form the decoder dictionary indexed by code. */
    int    *prefixOf = (int *)malloc(sizeof(int) * (size_t)kHashSize);
    uint8_t *suffixOf = (uint8_t *)malloc((size_t)kHashSize);
    uint8_t *scratch  = (uint8_t *)malloc((size_t)kHashSize);
    if (!prefixOf || !suffixOf || !scratch) {
        free(prefixOf); free(suffixOf); free(scratch);
        return (size_t)-1;
    }
    int nextCode = kFirstFreeCode;

    size_t out = 0;
    int previous = codes[0];
    if (previous < 0 || previous > 255 || out >= dstCap) {
        free(prefixOf); free(suffixOf); free(scratch);
        return (size_t)-1;
