    if (start + window_len > len) return len; /* not enough bytes for a window */

    uint32_t mask = (mask_bits >= 32) ? 0xFFFFFFFFu : ((1u << mask_bits) - 1u);

    BuzHash bh;
    buzhash_init(&bh, data + start, window_len);

