    int carry = 0;
    out->len = 0;
    for (int i = 0; i < BIG_MAX_DIGITS; i++) {
        uint32_t cur = acc[i] + carry;
        out->digits[out->len++] = (uint8_t)(cur % 10);
        carry = (int)(cur / 10);
