/*
 * Intrusive reference-counted smart pointer.
 *
 * Provides a minimal RefPtr<T> that manages the lifetime of objects carrying
 * their own reference count via the RefCounted base. The count is held inside
 * the object (intrusive), so copies are cheap and no separate control block is
 * allocated. The object is deleted exactly when the last RefPtr drops.
 */

#include <cstddef>

/*
 * Base class supplying an intrusive reference count. Types managed by RefPtr
 * must derive from this. The count starts at zero so a freshly constructed
 * object is owned by whatever RefPtr first adopts it.
 */
class RefCounted {
public:
    RefCounted() : ref_count_(0) {}

    /* Virtual so deleting through a RefCounted* runs the derived destructor. */
    virtual ~RefCounted() {}

    /* Increment the reference count by one. Called when a new owner appears. */
    void retain() {
        ref_count_++;
    }

    /*
     * Decrement the count and delete `this` when it reaches zero. Returns the
     * count remaining after the decrement so callers can observe destruction.
     * Must not be called on an object whose count is already zero.
     */
    long release() {
        ref_count_--;
        long remaining = ref_count_;
        if (remaining == 0) {
            delete this; /* last owner gone: reclaim the object */
        }
        return remaining;
    }

    /* Current number of live owners. Primarily for tests and diagnostics. */
    long use_count() const {
        return ref_count_;
    }

private:
    long ref_count_;
};

/*
 * Owning smart pointer for RefCounted-derived types. Each RefPtr that points
 * at an object contributes one to that object's reference count, and the
 * object lives until the count falls to zero.
 */
template <typename T>
class RefPtr {
public:
    /* Construct an empty pointer that owns nothing. */
    RefPtr() : ptr_(nullptr) {}

    /*
     * Adopt a raw pointer, taking one reference. Passing nullptr yields an
     * empty RefPtr. The object must not already be owned via a count this
     * RefPtr does not account for.
     */
    explicit RefPtr(T *ptr) : ptr_(ptr) {
        if (ptr_ != nullptr) {
            ptr_->retain();
        }
    }

    /* Copy constructor: share ownership by adding one reference. */
    RefPtr(const RefPtr &other) : ptr_(other.ptr_) {
        if (ptr_ != nullptr) {
            ptr_->retain();
        }
    }

    /*
     * Copy assignment with the standard retain-before-release ordering, which
     * keeps self-assignment and aliasing safe: we add our new reference before
     * dropping the old one. Returns *this.
     */
    RefPtr &operator=(const RefPtr &other) {
        if (other.ptr_ != nullptr) {
            other.ptr_->retain();
        }
        if (ptr_ != nullptr) {
            ptr_->release();
        }
        ptr_ = other.ptr_;
        return *this;
    }

    /* Destructor: drop this owner's reference. */
    ~RefPtr() {
        if (ptr_ != nullptr) {
            ptr_->release();
        }
    }

    /* Access the managed object. Undefined if the pointer is empty. */
    T *operator->() const {
        return ptr_;
    }

    /* Dereference the managed object. Undefined if the pointer is empty. */
    T &operator*() const {
        return *ptr_;
    }

    /* Raw pointer access without transferring ownership. */
    T *get() const {
        return ptr_;
    }

    /* True when this RefPtr currently owns an object. */
    bool valid() const {
        return ptr_ != nullptr;
    }

    /*
     * Release any held object and become empty. Decrements the old object's
     * count, deleting it if this was the last owner.
     */
    void reset() {
        if (ptr_ != nullptr) {
            ptr_->release();
            ptr_ = nullptr;
        }
    }

private:
    T *ptr_;
};

/* --- A concrete managed type, exercising the template above. --- */

/* A simple tree node whose children are themselves reference counted, so a
 * subtree is freed automatically once nothing points at its root. */
class Node : public RefCounted {
public:
    explicit Node(int value) : value_(value) {}

    int value() const { return value_; }

    /* Attach a child, retaining it for as long as this node holds it. */
    void set_child(const RefPtr<Node> &child) {
        child_ = child;
    }

private:
    int value_;
    RefPtr<Node> child_; /* keeps the child alive while the parent lives */
};

/*
 * Build a small parent/child chain and hand back the root. The returned RefPtr
 * is the sole external owner; dropping it tears down the whole chain.
 */
RefPtr<Node> build_chain(int root_value) {
    RefPtr<Node> root(new Node(root_value));
    RefPtr<Node> leaf(new Node(root_value + 1));
    root->set_child(leaf); /* leaf now has two owners: `leaf` and `root` */
    return root;           /* `leaf` drops on return, root keeps it alive */
}

/*
 * segment_intersect.c — exact integer segment intersection tests.
 *
 * Determines whether two closed line segments with integer endpoints intersect,
 * using only orientation (cross-product) signs. Because every test reduces to
 * the sign of an integer cross product, the result is exact — there are no
 * floating-point tolerances and no missed boundary cases. Handles the general
 * crossing case as well as all collinear-overlap special cases.
 */

#include <stdint.h>

/* A point on the integer lattice. */
typedef struct {
    int64_t x;
    int64_t y;
} Point;

/* A directed (but treated as undirected) segment from `a` to `b`. */
typedef struct {
    Point a;
    Point b;
} Segment;

/*
 * Orientation of the ordered triple (p, q, r) via the cross product of
 * (q - p) and (r - p).
 * Returns 0 if collinear, 1 if clockwise, 2 if counter-clockwise. The 0/1/2
 * encoding (rather than -1/0/1) lets callers compare orientations for equality
 * cheaply when deciding whether two points straddle a line.
 */
static int orientation(Point p, Point q, Point r) {
    int64_t val = (q.y - p.y) * (r.x - q.x) - (q.x - p.x) * (r.y - q.y);
    if (val == 0) return 0;
    return val > 0 ? 1 : 2;
}

/*
 * Given three collinear points p, q, r, test whether q lies on segment pr.
 * Precondition: the three points are already known to be collinear.
 * Returns 1 if q is within the axis-aligned bounding box of p and r (which,
 * for collinear points, means q is on the segment), 0 otherwise.
 */
static int onSegment(Point p, Point q, Point r) {
    int64_t minX = p.x < r.x ? p.x : r.x;
    int64_t maxX = p.x > r.x ? p.x : r.x;
    int64_t minY = p.y < r.y ? p.y : r.y;
    int64_t maxY = p.y > r.y ? p.y : r.y;
    return q.x >= minX && q.x <= maxX && q.y >= minY && q.y <= maxY;
}

/*
 * Test whether two closed segments intersect, including touching at an endpoint
 * and partial/total collinear overlap.
 *
 * The general case: the segments cross when each segment straddles the line of
 * the other, which happens exactly when the two endpoints of one segment have
 * opposite orientations relative to the other segment. The special cases handle
 * collinear configurations where an endpoint of one segment lies on the other.
 *
 * Returns 1 if the segments share at least one point, 0 if they are disjoint.
 */
int segmentsIntersect(Segment s1, Segment s2) {
    Point p1 = s1.a, q1 = s1.b;
    Point p2 = s2.a, q2 = s2.b;

    /* Orientation of each endpoint of one segment w.r.t. the other segment. */
    int o1 = orientation(p1, q1, p2);
    int o2 = orientation(p1, q1, q2);
    int o3 = orientation(p2, q2, p1);
    int o4 = orientation(p2, q2, q1);

    /* General case: the segments properly straddle each other. */
    if (o1 != o2 && o3 != o4) {
        return 1;
    }

    /* Special cases: a collinear endpoint that lands on the other segment. */
    if (o1 == 0 && onSegment(p1, p2, q1)) return 1; /* p2 lies on s1 */
    if (o2 == 0 && onSegment(p1, q2, q1)) return 1; /* q2 lies on s1 */
    if (o3 == 0 && onSegment(p2, p1, q2)) return 1; /* p1 lies on s2 */
    if (o4 == 0 && onSegment(p2, q1, q2)) return 1; /* q1 lies on s2 */

    return 0; /* no shared point */
}

/*
 * Determine whether a point lies exactly on a segment (endpoints included).
 * Returns 1 if `pt` is on segment `s`, 0 otherwise.
 */
int pointOnSegment(Point pt, Segment s) {
    /* Must be collinear with the endpoints and within their bounding box. */
    if (orientation(s.a, s.b, pt) != 0) return 0;
    return onSegment(s.a, pt, s.b);
}

/*
 * Classify how two segments relate without computing the meeting point.
 * Returns: 0 — disjoint; 1 — they cross at a single interior point; 2 — they
 * are collinear and overlap (share a sub-segment or a single shared endpoint
 * while collinear).
 */
int classifyIntersection(Segment s1, Segment s2) {
    if (!segmentsIntersect(s1, s2)) return 0;

    /* If all four cross-orientations are zero, the segments are collinear. */
    int collinear = orientation(s1.a, s1.b, s2.a) == 0 &&
                    orientation(s1.a, s1.b, s2.b) == 0;
    return collinear ? 2 : 1;
}

