int addEdge(Graph *graph, int src, int dest) {
    if (graph == NULL)
        return 0;
    /* Reject endpoints outside the valid vertex range. */
    if (src < 0 || src >= graph->numVertices)
        return 0;
    if (dest < 0 || dest >= graph->numVertices)
        return 0;
