 * Returns max - min, or 0 if the set is empty. O(n).
 */
int64_t stats_range(const int32_t *data, int32_t n) {
    if (n <= 0) return 0;
    return (int64_t)stats_max(data, n) - (int64_t)stats_min(data, n);
}

