        int64_t tmp = old_r - quotient * r;
        old_r = r; r = tmp;

        tmp = old_s - quotient * s;
        old_s = s; s = tmp;

        tmp = old_t - quotient * t;
        old_t = t; t = tmp;
    }

    if (out_x) *out_x = old_s;
    if (out_y) *out_y = old_t;
    return old_r;  /* old_r is now gcd(a, b) */
}

