#include <stdint.h>

/*
 * Exchange the values stored at two integer locations.
 *
 * Parameters:
 *   a, b - non-NULL pointers to the elements to swap.
 *
 * Returns: nothing. Mutates the two pointed-to values in place.
 */
static void swapInts(int32_t *a, int32_t *b) {
    int32_t held = *a;
    *a = *b;
    *b = held;
}

/*
